"""Deli Counter 0.240.0: a roof AC unit is an hvac unit and a club bar is a counter (the factory's roadmap 267).

Two of the library's box slots name a species Zoo already has, for want of a word in `PROP_SPECIES`; each claims
only its own volumes, and each species' genome holds their dims.

What it changes (anchored; each file pinned by hash; nothing written on a miss):
  * prop_species.py -- `roof_ac` in the `hvac_unit` row, `club_bar` in the `counter` row.
  * test_prop_species.py -- every library volume the two words reach, with its dims inside the genome; fails on
    0.239.0.
  * VERSION Deli Counter 0.239.0 -> Deli Counter 0.240.0, CHANGELOG.

Then `build.py --all` (prop_species.py is a build source), the suite and `check.py`.

Generated by `patches/dc_one_word_species/gen_dc_one_word_species.py` from a proven clone; its dry runs, the prove
run, the rebuild and the suite are beside it.

    python patches/patch_dc_one_word_species.py
"""
import hashlib
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[1]
REPO = ROOT / "deli_counter"
PINS = {'prop_species.py': '27ae3bc5642f205b', 'test_prop_species.py': 'f80a173c82bb50ba'}
EDITS = {'prop_species.py': [('lines 229-231', '    (("video_poker",), "video_poker"),\n    (("counter", "reception", "station", "island", "cage", "bar_",\n      "workbench", "tool_bench"), "counter"),\n', '    (("video_poker",), "video_poker"),\n    # A CLUB\'S BAR IS A COUNTER (0.240.0, the factory\'s roadmap 267): two\n    # `club_bar` volumes, 2.8 x 0.8 x 1.15, the serving counter of a pizza\n    # parlour\'s and a strip mall\'s bar, built as boxes for want of a word --\n    # `bar_` wants the underscore after it. Not `back_bar`, which the\n    # roadmap first named: that species is the shelving behind a bar, 1.8 m\n    # and up, and these stand 1.15.\n    (("counter", "reception", "station", "island", "cage", "bar_",\n      "club_bar", "workbench", "tool_bench"), "counter"),\n'), ('lines 237-237', '    (("hvac", "roof_unit"), "hvac_unit"),\n', '    # A ROOF AC UNIT IS AN HVAC UNIT (0.240.0, roadmap 267): three\n    # `roof_ac` volumes (the bank\'s, and the foundry\'s `roof_ac_block_a` and\n    # `_b`), 3.0-4.0 x 2.0 x 1.2-1.4, inside `hvac_unit`\'s genome. The word\n    # would also claim a `roof_access_...`; none exists, and\n    # `test_the_one_word_mappings_re_route_exactly_their_library_volumes`\n    # lists what it claims.\n    (("hvac", "roof_unit", "roof_ac"), "hvac_unit"),\n')], 'test_prop_species.py': [('lines 235-236', '\ndef test_a_species_that_owns_its_collision_gets_no_greybox_box(dc):\n', '\ndef test_the_one_word_mappings_re_route_exactly_their_library_volumes():\n    """Roadmap 267 (0.240.0): `roof_ac` to `hvac_unit` and `club_bar` to `counter`, each a box until then for want\n    of a word. Every library volume the two words reach, measured, with its size -- each inside its species\' genome\n    (hvac_unit 1.2-4.0 x 0.8-3.0 x 0.7-1.5, counter 0.8-12 x 0.5-2.0 x 0.85-1.2, long side first). FAILS ON 0.239.0:\n    both route to None."""\n    import glob\n    import json\n    here = os.path.dirname(os.path.abspath(__file__))\n    hits = []\n    for path in sorted(glob.glob(os.path.join(here, "specs", "*.json"))):\n        if os.path.basename(path).startswith("lf_"):\n            continue\n        with open(path, encoding="utf-8") as fh:\n            spec = json.load(fh)\n        for v in spec.get("volumes") or []:\n            name = (v.get("name") or "").lower()\n            if "roof_ac" in name or "club_bar" in name:\n                hits.append((os.path.basename(path)[:-5], v["name"], prop_species.species_for_name(name),\n                             sorted((float(v["size_x"]), float(v["size_y"])), reverse=True) + [float(v["size_z"])]))\n    assert sorted((h[0], h[1], h[2]) for h in hits) == [\n        ("bank", "roof_ac", "hvac_unit"),\n        ("foundry_heist_vertical", "roof_ac_block_a", "hvac_unit"),\n        ("foundry_heist_vertical", "roof_ac_block_b", "hvac_unit"),\n        ("primos_pizza", "club_bar", "counter"),\n        ("strip_retail_a01", "club_bar", "counter"),\n    ], hits\n    ranges = {"hvac_unit": ((1.2, 4.0), (0.8, 3.0), (0.7, 1.5)), "counter": ((0.8, 12.0), (0.5, 2.0), (0.85, 1.2))}\n    for _spec, _name, species, dims in hits:\n        assert all(lo <= v <= hi for v, (lo, hi) in zip(dims, ranges[species])), (species, dims)\n\n\ndef test_a_species_that_owns_its_collision_gets_no_greybox_box(dc):\n')]}
NEW_FILES = {}
CHANGELOG = '## [0.240.0] - a roof AC unit is an hvac unit and a club bar is a counter: two boxes get the word they lacked\n\n**The factory\'s roadmap 267, its one-word mappings first.** Read against the walker\'s asset wishlist, 1,486 of the\nlibrary\'s prop slots named no species and Zoo built each as a plain box (the factory\'s\n`docs/findings/asset_wishlist_2026-10-19/box_slots.py`); a few of them name a species Zoo already has, for want of a\nword in `PROP_SPECIES`. Each candidate was checked before it was added: every library volume the new word would\nclaim, and whether the species\' genome holds those volumes\' dims in the slot\'s own orientation, which is how Zoo\'s\n`_species_fit` asks.\n\n### Changed\n- `PROP_SPECIES`: `roof_ac` joins the `hvac_unit` row. It claims 3 volumes, the bank\'s `roof_ac` and the foundry\'s\n  `roof_ac_block_a` / `_b` (3.0 to 4.0 x 2.0 x 1.2 to 1.4 m), all inside the genome.\n- `club_bar` joins the `counter` row. It claims 2 volumes, primos_pizza\'s and strip_retail_a01\'s 2.8 x 0.8 x 1.15 m\n  serving bar (`bar_` wanted the underscore). Not `back_bar`, which the roadmap first named: that species is the\n  shelving behind a bar, 1.8 m and up.\n\n### Not changed, and why\n- `container` -> `cargo_container`: freight_terminal_a01\'s four 6.0 x 2.4 x 2.6 m containers would be recorded long\n  side first, as every hinted volume is (`long_axis_first`). Zoo\'s container is long in DEPTH (width 2.3 to 2.5), and\n  `_species_fit` asks in the slot\'s own orientation, so all four would be built as the box, "would fit turned 90\n  degrees". That needs a rule for species that are long in depth, and the composer infers the same turn from a\n  slot\'s extents, so it is its own change.\n- `barrier` -> `jersey_barrier`: arena_a02\'s four 3.0 x 0.8 x 1.2 m barriers are a crowd\'s, not a road\'s. That is\n  the walker\'s call, not a word\'s.\n\n### Tests\n- `test_prop_species.py`: `test_the_one_word_mappings_re_route_exactly_their_library_volumes`, every library volume\n  the two words reach, with its species and its dims inside the genome. It fails on 0.239.0, where both route to\n  None.\n\n'
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.239.0', 'Deli Counter 0.240.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
